-- Floor level surveys: relative floor levels (mm) read on site and marked on
-- a floorplan, with the inspector's classification of the result. One
-- survey per floorplan. Written by the inspector app (newest edit wins).
-- Safe to run more than once.

create table if not exists public.level_surveys (
  -- Generated by the phone so offline edits keep their identity.
  id uuid primary key,
  job_id uuid not null references public.jobs(id) on delete cascade,
  floorplan_id uuid references public.job_floorplans(id) on delete set null,
  -- [{"x": 0..1, "y": 0..1, "mm": number}, ...]
  readings jsonb not null default '[]'::jsonb,
  instrument text,
  datum text,
  result text,
  notes text,
  deleted_at timestamptz,
  client_updated_at timestamptz not null,
  updated_by_staff_id uuid references public.staff(id) on delete set null,
  created_at timestamptz not null default now(),
  sync_rev bigint not null default nextval('public.inspection_sync_rev_seq'),
  updated_at timestamptz not null default now(),
  constraint level_surveys_readings_check check (
    jsonb_typeof(readings) = 'array' and jsonb_array_length(readings) <= 300
  ),
  constraint level_surveys_result_check check (
    result is null or result in ('minor', 'further_investigation', 'major')
  ),
  constraint level_surveys_text_check check (
    char_length(coalesce(instrument, '')) <= 120
    and char_length(coalesce(datum, '')) <= 200
    and char_length(coalesce(notes, '')) <= 2000
  )
);

create index if not exists level_surveys_job_idx on public.level_surveys (job_id, sync_rev);

drop trigger if exists level_surveys_bump_rev on public.level_surveys;
create trigger level_surveys_bump_rev
before update on public.level_surveys
for each row execute function private.bump_sync_rev();

alter table public.level_surveys enable row level security;
revoke all on table public.level_surveys from anon, authenticated;
drop policy if exists level_surveys_select_assigned on public.level_surveys;
create policy level_surveys_select_assigned on public.level_surveys
for select to authenticated using (private.can_view_job(job_id));
grant select on public.level_surveys to authenticated;

create or replace function public.app_sync_level_surveys(
  p_actor_user_id uuid,
  p_job_id uuid,
  p_surveys jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_staff public.staff%rowtype;
  v_item jsonb;
  v_existing public.level_surveys%rowtype;
  v_applied uuid[] := '{}';
  v_stale uuid[] := '{}';
  v_id uuid;
  v_plan uuid;
  v_client_at timestamptz;
begin
  v_staff := private.app_actor_for_job(p_actor_user_id, p_job_id);
  if jsonb_typeof(p_surveys) <> 'array' or jsonb_array_length(p_surveys) > 50 then
    raise exception 'Send between 0 and 50 level surveys at a time.';
  end if;

  for v_item in select * from jsonb_array_elements(p_surveys) loop
    v_id := (v_item->>'id')::uuid;
    v_client_at := (v_item->>'clientUpdatedAt')::timestamptz;
    v_plan := nullif(v_item->>'floorplanId', '')::uuid;
    select * into v_existing from public.level_surveys where id = v_id for update;
    if found then
      if v_existing.job_id <> p_job_id then raise exception 'Level survey belongs to another job.'; end if;
      if v_existing.client_updated_at > v_client_at then
        v_stale := v_stale || v_id;
        v_existing := null;
        continue;
      end if;
    end if;
    if v_plan is not null and not exists (
      select 1 from public.job_floorplans where id = v_plan and job_id = p_job_id
    ) then
      raise exception 'Floorplan does not belong to this job.';
    end if;

    insert into public.level_surveys (
      id, job_id, floorplan_id, readings, instrument, datum, result, notes,
      deleted_at, client_updated_at, updated_by_staff_id
    ) values (
      v_id, p_job_id, v_plan,
      coalesce(v_item->'readings', '[]'::jsonb),
      nullif(v_item->>'instrument', ''), nullif(v_item->>'datum', ''),
      nullif(v_item->>'result', ''), nullif(v_item->>'notes', ''),
      case when (v_item->>'deleted')::boolean then coalesce(v_existing.deleted_at, now()) else null end,
      v_client_at, v_staff.id
    )
    on conflict (id) do update set
      floorplan_id = excluded.floorplan_id,
      readings = excluded.readings,
      instrument = excluded.instrument,
      datum = excluded.datum,
      result = excluded.result,
      notes = excluded.notes,
      deleted_at = excluded.deleted_at,
      client_updated_at = excluded.client_updated_at,
      updated_by_staff_id = excluded.updated_by_staff_id;

    v_applied := v_applied || v_id;
    v_existing := null;
  end loop;

  if cardinality(v_applied) > 0 then
    insert into public.audit_events (job_id, event_type, actor_type, actor_id, event_data)
    values (p_job_id, 'app_level_surveys_synced', 'staff', v_staff.id::text,
      jsonb_build_object('applied', cardinality(v_applied), 'stale', cardinality(v_stale)));
  end if;
  return jsonb_build_object('applied', to_jsonb(v_applied), 'stale', to_jsonb(v_stale));
end;
$$;

revoke all on function public.app_sync_level_surveys(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.app_sync_level_surveys(uuid, uuid, jsonb) to service_role;
